INSERT INTO resources (scope_id, kind, schema_version, name, config, status) SELECT p.scope_id,'Skill',2,'Kafka 健康诊断',jsonb_build_object('summary','Kafka 集群、Broker、Topic、分区、消费组和积压的只读诊断。','owner','OpsKeeper builtin'),'active' FROM platforms p WHERE p.code='default' ON CONFLICT (scope_id, kind, lower(name)) WHERE deleted_at IS NULL DO NOTHING;
INSERT INTO skill_versions (skill_resource_id,version,manifest,input_schema,output_schema,tools,risk_level,status,published_at) SELECT r.id,COALESCE((SELECT max(v.version)+1 FROM skill_versions v WHERE v.skill_resource_id=r.id),1),jsonb_build_object('name',r.name,'description',r.config->>'summary','instruction','调用 Kafka 固定只读工具；不要请求或建议管理操作。','target_kinds','["Kafka"]'::jsonb),'{}'::jsonb,'{}'::jsonb,'[{"name":"kafka_health"},{"name":"kafka_brokers"},{"name":"kafka_topics"},{"name":"kafka_consumer_groups"},{"name":"kafka_consumer_lag"},{"name":"kafka_cluster_info"},{"name":"kafka_topic_partitions"}]'::jsonb,'read_only','published',now() FROM resources r WHERE r.kind='Skill' AND r.name='Kafka 健康诊断' AND r.config->>'owner'='OpsKeeper builtin';
